function doesAliceWin(s) {
  // Exhaustive game search with memoisation. Only which characters are vowels matters,
  // so the game is played on a pattern of '1' (vowel) and '0' (consonant).
  const pattern = [...s].map(c => ('aeiou'.includes(c) ? '1' : '0')).join('');
  const memo = new Map();
  const moverWins = (rest, aliceToMove) => {
    const key = (aliceToMove ? 'A:' : 'B:') + rest;
    if (memo.has(key)) return memo.get(key);
    let win = false;
    for (let i = 0; i < rest.length && !win; i++) {
      let vowels = 0;
      for (let j = i; j < rest.length && !win; j++) {
        if (rest[j] === '1') vowels++;
        const allowed = aliceToMove ? vowels % 2 === 1 : vowels % 2 === 0;
        if (allowed && !moverWins(rest.slice(0, i) + rest.slice(j + 1), !aliceToMove)) win = true;
      }
    }
    memo.set(key, win);
    return win;
  };
  return moverWins(pattern, true);
}

