function generate(rand, size) {
  const consonants = 'bcdfghjklmnpqrstvwxyz';
  const vowels = 'aeiou';
  const pick = text => text[Math.floor(rand() * text.length)];
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 8);
  // 0: no vowels, 1: exactly one vowel, 2: a few vowels, 3: any letters.
  const shape = Math.floor(rand() * 4);
  const chars = Array.from({ length: n }, () => pick(shape === 3 ? vowels + consonants : consonants));
  if (shape === 1) chars[Math.floor(rand() * n)] = pick(vowels);
  if (shape === 2) for (let i = 0; i < n; i++) if (rand() < 0.25) chars[i] = pick(vowels);
  return [chars.join('')];
}
